import 'package:firebase_auth/firebase_auth.dart'; import 'package:flutter/material.dart';
import '../../../services/safety/offline_safety_service.dart'; import '../../messenger/presentation/messenger_screen.dart';
class AurenOfflineSafetyScreen extends StatefulWidget{const AurenOfflineSafetyScreen({super.key});@override State<AurenOfflineSafetyScreen> createState()=>_AurenOfflineSafetyScreenState();}
class _AurenOfflineSafetyScreenState extends State<AurenOfflineSafetyScreen>{String city='',country='';
void _area(){final a=TextEditingController(text:city),b=TextEditingController(text:country);showDialog(context:context,builder:(ctx)=>AlertDialog(title:const Text('منطقة الرحلة'),content:Column(mainAxisSize:MainAxisSize.min,children:[TextField(controller:a,decoration:const InputDecoration(labelText:'المدينة')),TextField(controller:b,decoration:const InputDecoration(labelText:'الدولة'))]),actions:[TextButton(onPressed:()=>Navigator.pop(ctx),child:const Text('إلغاء')),FilledButton(onPressed:(){setState((){city=a.text;country=b.text;});Navigator.pop(ctx);},child:const Text('حفظ'))]));}
@override Widget build(BuildContext context){final uid=FirebaseAuth.instance.currentUser?.uid;return Scaffold(appBar:AppBar(title:const Text('Offline Navigation + Safety'),actions:[IconButton(icon:const Icon(Icons.auto_awesome),onPressed:()=>Navigator.push(context,MaterialPageRoute(builder:(_)=>const MessengerScreen(initialPrompt:'ساعدني في خطة تنقل آمنة عند ضعف الإنترنت، واذكر نقاط الطوارئ المهمة في المنطقة.')))),IconButton(onPressed:_area,icon:const Icon(Icons.location_city))]),body:uid==null?const Center(child:Text('سجّل الدخول لاستخدام الأمان.')):Column(children:[const Padding(padding:EdgeInsets.all(12),child:Text('المسارات المحفوظة تحتاج إلى حزمة خرائط محلية/GPS من الجهاز؛ هذه الشاشة تحفظ بيانات المسارات وتعرض نقاط الأمان عند توفر الشبكة.')),Expanded(child:StreamBuilder<List<AurenSafetyPlace>>(stream:AurenOfflineSafetyService.instance.watchPlaces(city:city,country:country),builder:(c,s){if(s.hasError)return const Center(child:Text('تعذر تحميل نقاط الأمان.'));if(!s.hasData)return const Center(child:CircularProgressIndicator());if(s.data!.isEmpty)return const Center(child:Text('لا توجد نقاط أمان مسجلة لهذه المنطقة حالياً.'));return ListView(children:s.data!.map((x)=>ListTile(leading:const Icon(Icons.emergency_outlined),title:Text(x.name),subtitle:Text(x.type+' • '+x.city+', '+x.country)).toList());}))]) );}}
